import app from 'flarum/forum/app';
import { override } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import { revealed, matchedWarnings } from './cwState';

// Navigating straight into a thread (search result, shared link) must not
// bypass the reader's content filters: block the page with an interstitial
// until they opt in.
export default function addCwInterstitial() {
  override('flarum/forum/components/DiscussionPage', 'view', function (original) {
    const discussion = this.discussion;
    if (this.loading || !discussion || revealed.has(discussion.id())) {
      return original();
    }
    const matched = matchedWarnings(discussion);
    if (!matched.length) {
      return original();
    }
    const trans = (key, data) => app.translator.trans("ao3-companion.forum.interstitial.".concat(key), data);
    return m("div", {
      className: "DiscussionPage Ao3Interstitial"
    }, m("div", {
      className: "container"
    }, m("div", {
      className: "Ao3Interstitial-card"
    }, m(Icon, {
      name: "fas fa-eye-slash",
      className: "Ao3Interstitial-icon"
    }), m("h2", null, trans('heading')), m("p", null, trans('body', {
      warnings: matched.join(', ')
    })), m("div", {
      className: "Ao3Interstitial-actions"
    }, m(Button, {
      className: "Button",
      onclick: () => {
        app.history.canGoBack() ? app.history.back() : m.route.set('/');
      }
    }, trans('back')), m(Button, {
      className: "Button Button--primary",
      onclick: () => {
        revealed.add(discussion.id());
        m.redraw();
      }
    }, trans('show'))))));
  });
}